/**
 * Curated icon category source for the vendor sets (material, carbon, lucide).
 *
 * Maps each vendor icon id to its {@link IconCategoryPath}. This is the single
 * place categories are stored for the vendor sets. `getIconCategoryFromId`
 * reads it directly and falls back to the shared keyword table in
 * `category-keywords.ts` for an id not listed here, so a newly seeded icon
 * still lands in a category without a hand edit.
 *
 * Edit an entry to correct one icon. The seldon set keeps its own folder-derived
 * map in `catalog/seldon/category-map.ts`, since it ships component files.
 */
